<?php declare(strict_types=1);
require_once __DIR__.'/../../../src/Finance/Balance/BalancePeriodSourceCatalogue.php';
$sourceCatalogue=new \Kulturhus\Verein\BalancePeriodSourceCatalogue($db,(string)$_SESSION['actor']);$sourceCataloguePage=null;$sourceCatalogueError='';$sourceCatalogueRow=null;$choice=null;$selected=input($old,'source_type')!==''&&input($old,'source_id')!==''?input($old,'source_type').':'.input($old,'source_id'):input($_GET,'period_source');
$sourceCatalogueInput=in_array(input($old,'action'),['balance-period-source-import','balance-period-source-correct'],true)?$old:$_GET;
$sourceFilterRaw=[];foreach(\Kulturhus\Verein\BalancePeriodSourceQuery::FIELDS as$key)$sourceFilterRaw[$key]=input($sourceCatalogueInput,$key);$sourceKind=explode(':',$selected,2)[0]??'invoice';if(!in_array($sourceKind,['invoice','transaction','depreciation'],true))$sourceKind='invoice';
try{
 if(array_key_exists('period_source',$sourceCatalogueInput)&&!is_string($sourceCatalogueInput['period_source']))throw new DomainException('Vollständigen Belegbezug prüfen.',422);
 $sourceCataloguePage=$sourceCatalogue->page($r['period'],$sourceCatalogueInput,$sourceKind);$sourceFilterRaw=$sourceCataloguePage['query'];
 if($selected!==''){[$sourceSelectedType,$sourceSelectedId]=array_pad(explode(':',$selected,2),2,'');$sourceCatalogueRow=$sourceCatalogue->selected($r['period'],$sourceSelectedType,$sourceSelectedId);$choice=['type'=>$sourceCatalogueRow['type'],'id'=>$sourceCatalogueRow['id'],'date'=>$sourceCatalogueRow['performance_date'],'label'=>$sourceCatalogueRow['description'],'owner'=>$sourceCatalogueRow['owner_period']!==null?['period_id'=>$sourceCatalogueRow['owner_period']]:null];}
}catch(DomainException$ex){$sourceCatalogueError=$ex->getMessage();if(!headers_sent())http_response_code(in_array($ex->getCode(),[403,404,422],true)?$ex->getCode():422);$choice=null;}
$sourceKinds=['invoice'=>'Rechnungen und Beiträge','transaction'=>'Bankumsätze','depreciation'=>'Anlagenwerte'];$sourceStates=['all'=>'Alle ursprünglichen Übernahmen','open'=>'Noch nicht im Journal übernommen','current'=>'In diesem Zeitraum übernommen','other'=>'In einem anderen Zeitraum übernommen'];$sourceDirections=['all'=>'Alle Richtungen','in'=>'Eingang','out'=>'Ausgang'];
$sourceCatalogueUrl=static function(array$query,?string$selection=null)use($periodId):string{return url(['view'=>'finance','tab'=>'tax','balance'=>'1','periods'=>'1','period_id'=>$periodId]+($selection===null?[]:['period_source'=>$selection])+$query).'#period-sources';};
$sourceOwnerLabel=static function(?string$id)use($periodId,$sourceText):string{if($id===null)return$sourceText('Noch nicht im Journal übernommen');if($id===$periodId)return$sourceText('In diesem Zeitraum übernommen');return$sourceText('In einem anderen Zeitraum übernommen');};
?>
<div data-period-source-catalogue>
<?php if($sourceCatalogueRow!==null): ?><section class="card" data-period-source-selected><h3><?= e($sourceText('Ausgewähltes Original')) ?></h3><p><?= e(($sourceCatalogueRow['display_number']!==''?$sourceCatalogueRow['display_number'].' · ':'').$sourceCatalogueRow['description']) ?></p><p><?= e($sourceOwnerLabel($sourceCatalogueRow['owner_period'])) ?></p><p><?= e($sourceText('Der ausgewählte Beleg bleibt unabhängig von Suchseite und Filtern ausdrücklich ausgewählt.')) ?></p></section><?php endif ?>
<?php if($sourceCatalogueRow!==null): ?><details data-period-source-search-more><summary><?= e($sourceText('Weitere Originale suchen')) ?></summary><?php endif ?>
