<form method="get" class="card" data-period-source-search><?= hidden('view','finance').hidden('tab','tax').hidden('balance','1').hidden('periods','1').hidden('period_id',$periodId).hidden('source_page','1').($selected!==''?hidden('period_source',$selected):'') ?>
<div class="form-grid"><label><?= e($sourceText('Belegart')) ?><select class="form-control" name="source_kind"><?php foreach($sourceKinds as$value=>$label): ?><option value="<?= e($value) ?>" <?= ($sourceFilterRaw['source_kind']?:$sourceKind)===$value?'selected':'' ?>><?= e($sourceText($label)) ?></option><?php endforeach ?></select></label>
<label><?= e($sourceText('Name, Rechnungsnummer oder Beschreibung suchen')) ?><input class="form-control" type="search" name="source_q" maxlength="200" value="<?= e($sourceFilterRaw['source_q']) ?>"></label>
<label><?= e($sourceText('Übernahme ins Journal')) ?><select class="form-control" name="source_state"><?php foreach($sourceStates as$value=>$label): ?><option value="<?= e($value) ?>" <?= ($sourceFilterRaw['source_state']?:'all')===$value?'selected':'' ?>><?= e($sourceText($label)) ?></option><?php endforeach ?></select></label>
<label><?= e($sourceText('Richtung')) ?><select class="form-control" name="source_direction"><?php foreach($sourceDirections as$value=>$label): ?><option value="<?= e($value) ?>" <?= ($sourceFilterRaw['source_direction']?:'all')===$value?'selected':'' ?>><?= e($sourceText($label)) ?></option><?php endforeach ?></select></label>
<label><?= e($sourceText('Beleg- oder Buchungsdatum von')) ?><input class="form-control" type="date" name="source_from" value="<?= e($sourceFilterRaw['source_from']) ?>"></label><label><?= e($sourceText('Beleg- oder Buchungsdatum bis')) ?><input class="form-control" type="date" name="source_to" value="<?= e($sourceFilterRaw['source_to']) ?>"></label>
<label><?= e($sourceText('Genauer Betrag ohne Vorzeichen (Euro)')) ?><input class="form-control" inputmode="decimal" name="source_amount" value="<?= e($sourceFilterRaw['source_amount']) ?>"></label></div>
<p class="form-text"><?= e($sourceText('Beträge ohne Tausendertrennzeichen angeben. Den Geldfluss über die Richtung auswählen. Anlagenwerte ohne Betrags- und Richtungsfilter suchen.')) ?></p><button class="btn btn-solid theme-primary"><?= e($sourceText('Originale suchen')) ?></button> <a class="btn btn-outline" href="<?= e($sourceCatalogueUrl(['source_kind'=>$sourceFilterRaw['source_kind']?:$sourceKind],$selected?:null)) ?>"><?= e($sourceText('Suche zurücksetzen')) ?></a></form>
<?php if($sourceCatalogueError!==''): ?><p role="alert"><?= e($sourceText($sourceCatalogueError)) ?></p><?php endif ?>
