<p role="status" data-period-source-count><?= $sourceCataloguePage['total'] ?> · <?= e($sourceText($sourceKinds[$sourceQuery['source_kind']])) ?> · <?= e($sourceText('Seite')) ?> <?= $sourceCataloguePage['page'] ?> / <?= $sourceCataloguePage['pages'] ?></p>
<p><?= e($sourceText('Rechnungen und Beiträge')) ?> <?= $sourceCataloguePage['counts']['invoice'] ?> · <?= e($sourceText('Bankumsätze')) ?> <?= $sourceCataloguePage['counts']['transaction'] ?> · <?= e($sourceText('Anlagenwerte')) ?> <?= $sourceCataloguePage['counts']['depreciation'] ?></p>
<?php if(!$sourceCataloguePage['rows']): ?><p><?= e($sourceText('Für diese Suche wurden keine passenden Originale gefunden.')) ?></p><?php endif ?>
<?php ob_start(); ?><?php if($sourceCataloguePage['pages']>1): ?><nav aria-label="<?= e($sourceText('Seiten der vollständigen Belegsuche')) ?>"><?php if($sourceCataloguePage['page']>1): ?><a class="btn btn-outline" href="<?= e($sourceCatalogueUrl(\Kulturhus\Verein\BalancePeriodSourceQuery::page($sourceQuery,$sourceCataloguePage['page']-1),$selected?:null)) ?>"><?= e($sourceText('Vorherige Seite')) ?></a><?php endif ?><?php if($sourceCataloguePage['page']<$sourceCataloguePage['pages']): ?><a class="btn btn-outline" href="<?= e($sourceCatalogueUrl(\Kulturhus\Verein\BalancePeriodSourceQuery::page($sourceQuery,$sourceCataloguePage['page']+1),$selected?:null)) ?>"><?= e($sourceText('Nächste Seite')) ?></a><?php endif ?></nav><?php endif ?><?php $sourceCataloguePagesHtml=ob_get_clean();echo $sourceCataloguePagesHtml; ?>
